def validate_content(errors: list[str]) -> None:
    required = discover_content_files(errors)
    expected_domains = {
        "factions",
        "heroes",
        "units",
        "army_groups",
        "towns",
        "buildings",
        "resource_sites",
        "biomes",
        "terrain_grammar",
        "terrain_layers",
        "map_objects",
        "neutral_dwellings",
        "artifacts",
        "spells",
        "encounters",
        "scenarios",
        "campaigns",
    }
    for domain in sorted(expected_domains):
        ensure(domain in required, errors, f"ContentService.gd is missing expected content path for {domain}")

    payloads = {}
    for key, path in required.items():
        ensure(path.exists(), errors, f"Missing content file: {path.relative_to(ROOT)}")
        if path.exists():
            payloads[key] = load_json(path)

    if errors:
        return

    factions = items_index(payloads["factions"])
    heroes = items_index(payloads["heroes"])
    units = items_index(payloads["units"])
    army_groups = items_index(payloads["army_groups"])
    towns = items_index(payloads["towns"])
    buildings = items_index(payloads["buildings"])
    resource_sites = items_index(payloads["resource_sites"])
    biomes = items_index(payloads["biomes"])
    map_objects = items_index(payloads["map_objects"])
    neutral_dwellings = items_index(payloads["neutral_dwellings"])
    artifacts = items_index(payloads["artifacts"])
    artifact_sets = artifact_sets_index(payloads["artifacts"])
    spells = items_index(payloads["spells"])
    encounters = items_index(payloads["encounters"])
    scenarios = items_index(payloads["scenarios"])
    campaigns = items_index(payloads["campaigns"])
    ensure(len(heroes) >= 9, errors, "Release hero content must author at least nine commanders")
    ensure(len(scenarios) >= 10, errors, "Historical scenario compatibility archive must preserve at least ten distinct fronts")
    validate_native_scenario_reset(errors, payloads["scenarios"], payloads["campaigns"])
    campaign_scenario_ids = {
        str(scenario_entry.get("scenario_id", ""))
        for campaign in campaigns.values()
        for scenario_entry in campaign.get("scenarios", [])
        if isinstance(scenario_entry, dict) and str(scenario_entry.get("scenario_id", ""))
    }
    skirmish_scenario_ids: list[str] = []
    deadline_loss_scenario_ids: set[str] = set()
    deadline_loss_skirmish_scenario_ids: set[str] = set()
    scenario_player_factions: set[str] = set()
    scenario_hero_ids: set[str] = set()
    authored_unit_ability_ids: set[str] = set()

    for faction_id, faction in factions.items():
        ensure(bool(str(faction.get("identity_summary", ""))), errors, f"Faction {faction_id} must define identity_summary")
        for town_id in faction.get("town_ids", []):
            ensure(str(town_id) in towns, errors, f"Faction {faction_id} references missing town {town_id}")
        for hero_id in faction.get("hero_ids", []):
            ensure(str(hero_id) in heroes, errors, f"Faction {faction_id} references missing hero {hero_id}")
        economy = faction.get("economy", {})
        ensure(isinstance(economy, dict) and bool(economy), errors, f"Faction {faction_id} must define an economy profile")
        if isinstance(economy, dict):
            base_income = economy.get("base_income", {})
            ensure(isinstance(base_income, dict), errors, f"Faction {faction_id} economy base_income must be a dictionary")
            if "pressure_bonus" in economy:
                ensure(int(economy.get("pressure_bonus", 0)) >= 0, errors, f"Faction {faction_id} economy pressure_bonus must be >= 0")
            per_category_income = economy.get("per_category_income", {})
            ensure(isinstance(per_category_income, dict) and bool(per_category_income), errors, f"Faction {faction_id} economy must define per_category_income")
            if isinstance(per_category_income, dict):
                for category, resources in per_category_income.items():
                    ensure(str(category) in SUPPORTED_BUILDING_CATEGORIES, errors, f"Faction {faction_id} economy uses unsupported building category {category}")
                    ensure(isinstance(resources, dict) and bool(resources), errors, f"Faction {faction_id} economy category {category} must define resource income")
        recruitment = faction.get("recruitment", {})
        ensure(isinstance(recruitment, dict) and bool(recruitment), errors, f"Faction {faction_id} must define a recruitment profile")
        if isinstance(recruitment, dict):
            if "readiness_bonus" in recruitment:
                ensure(int(recruitment.get("readiness_bonus", 0)) >= 0, errors, f"Faction {faction_id} recruitment readiness_bonus must be >= 0")
            growth_bonus = recruitment.get("growth_bonus", {})
            ensure(isinstance(growth_bonus, dict) and bool(growth_bonus), errors, f"Faction {faction_id} recruitment must define growth_bonus")
            if isinstance(growth_bonus, dict):
                for unit_id, amount in growth_bonus.items():
                    ensure(str(unit_id) in units, errors, f"Faction {faction_id} recruitment references missing growth unit {unit_id}")
                    ensure(int(amount) > 0, errors, f"Faction {faction_id} recruitment growth bonus must be > 0 for {unit_id}")
            discounts = recruitment.get("cost_discount_percent", {})
            ensure(isinstance(discounts, dict) and bool(discounts), errors, f"Faction {faction_id} recruitment must define cost_discount_percent")
            if isinstance(discounts, dict):
                for unit_id, amount in discounts.items():
                    ensure(str(unit_id) in units, errors, f"Faction {faction_id} recruitment references missing discount unit {unit_id}")
                    ensure(0 < int(amount) < 100, errors, f"Faction {faction_id} recruitment discount must be between 1 and 99 for {unit_id}")
        if faction_id in RELEASE_PLAYER_FACTIONS:
            ensure(len([str(value) for value in faction.get("hero_ids", [])]) >= 4, errors, f"Faction {faction_id} must author at least four playable heroes for release-facing roster depth")
            enemy_strategy = faction.get("enemy_strategy", {})
            ensure(isinstance(enemy_strategy, dict) and bool(enemy_strategy), errors, f"Faction {faction_id} must define enemy_strategy for hostile-empire personality")
            if isinstance(enemy_strategy, dict):
                for section, required_keys in ENEMY_STRATEGY_KEYS.items():
                    bucket = enemy_strategy.get(section, {})
                    ensure(isinstance(bucket, dict) and bool(bucket), errors, f"Faction {faction_id} enemy_strategy must define non-empty {section}")
                    if isinstance(bucket, dict):
                        for key in required_keys:
                            ensure(key in bucket, errors, f"Faction {faction_id} enemy_strategy {section} is missing {key}")

    for hero_id, hero in heroes.items():
        faction_id = str(hero.get("faction_id", ""))
        ensure(faction_id in factions, errors, f"Hero {hero_id} references missing faction")
        if faction_id in factions:
            ensure(hero_id in [str(value) for value in factions[faction_id].get("hero_ids", [])], errors, f"Hero {hero_id} must be listed in faction {faction_id} hero_ids")
        ensure(bool(str(hero.get("roster_summary", ""))), errors, f"Hero {hero_id} must define roster_summary")
        ensure(bool(str(hero.get("identity_summary", ""))), errors, f"Hero {hero_id} must define identity_summary")
        ensure(int(hero.get("base_movement", 0)) > 0, errors, f"Hero {hero_id} must define base_movement > 0")
        recruit_cost = hero.get("recruit_cost", {})
        if "recruit_cost" in hero:
            ensure(isinstance(recruit_cost, dict), errors, f"Hero {hero_id} recruit_cost must be a dictionary")
        if isinstance(recruit_cost, dict):
            for resource_key, amount in recruit_cost.items():
                ensure(bool(str(resource_key)), errors, f"Hero {hero_id} recruit_cost cannot contain an empty resource key")
                ensure(int(amount) >= 0, errors, f"Hero {hero_id} recruit_cost must be >= 0 for {resource_key}")
        starting_specialties = hero.get("starting_specialties", [])
        ensure(isinstance(starting_specialties, list) and bool(starting_specialties), errors, f"Hero {hero_id} must define non-empty starting_specialties")
        if isinstance(starting_specialties, list):
            for specialty_id in starting_specialties:
                ensure(str(specialty_id) in VALID_SPECIALTY_IDS, errors, f"Hero {hero_id} uses unsupported starting specialty {specialty_id}")
        specialty_focus_ids = hero.get("specialty_focus_ids", [])
        ensure(isinstance(specialty_focus_ids, list) and len(specialty_focus_ids) >= 2, errors, f"Hero {hero_id} must define at least two specialty_focus_ids")
        if isinstance(specialty_focus_ids, list):
            for specialty_id in specialty_focus_ids:
                ensure(str(specialty_id) in VALID_SPECIALTY_IDS, errors, f"Hero {hero_id} uses unsupported specialty focus {specialty_id}")
        battle_traits = hero.get("battle_traits", [])
        ensure(isinstance(battle_traits, list) and bool(battle_traits), errors, f"Hero {hero_id} must define non-empty battle_traits")
        if isinstance(battle_traits, list):
            for trait_id in battle_traits:
                ensure(str(trait_id) in VALID_BATTLE_TRAIT_IDS, errors, f"Hero {hero_id} uses unsupported battle trait {trait_id}")
        for spell_id in hero.get("starting_spell_ids", []):
            ensure(str(spell_id) in spells, errors, f"Hero {hero_id} references missing starting spell {spell_id}")

    for unit_id, unit in units.items():
        if is_neutral_unit(unit):
            ensure(str(unit.get("faction_id", "")) == "", errors, f"Neutral unit {unit_id} must not belong to a faction ladder")
            ensure(str(unit.get("content_status", "")) == "neutral_dwelling_slice", errors, f"Neutral unit {unit_id} must be marked as neutral_dwelling_slice")
        else:
            ensure(str(unit.get("faction_id", "")) in factions, errors, f"Unit {unit_id} references missing faction")
        ensure(int(unit.get("hp", 0)) > 0, errors, f"Unit {unit_id} must define hp > 0")
        ensure(int(unit.get("max_damage", 0)) >= int(unit.get("min_damage", 0)) > 0, errors, f"Unit {unit_id} has invalid damage range")
        ensure(0 <= int(unit.get("spell_resistance_pct", 0)) <= 75, errors, f"Unit {unit_id} spell_resistance_pct must be between 0 and 75")
        ensure(0 <= int(unit.get("control_resistance_pct", 0)) <= 80, errors, f"Unit {unit_id} control_resistance_pct must be between 0 and 80")
        school_resistance = unit.get("spell_school_resistance_pct", {})
        ensure(isinstance(school_resistance, dict), errors, f"Unit {unit_id} spell_school_resistance_pct must be a dictionary")
        if isinstance(school_resistance, dict):
            for school_id, amount in school_resistance.items():
                ensure(str(school_id) in SUPPORTED_SPELL_SCHOOLS, errors, f"Unit {unit_id} uses unsupported school resistance {school_id}")
                ensure(0 <= int(amount) <= 75, errors, f"Unit {unit_id} school resistance for {school_id} must be between 0 and 75")
        status_immunity_ids = unit.get("status_immunity_ids", [])
        ensure(isinstance(status_immunity_ids, list), errors, f"Unit {unit_id} status_immunity_ids must be a list")
        if isinstance(status_immunity_ids, list):
            for status_id in status_immunity_ids:
                ensure(str(status_id) in SUPPORTED_STATUS_EFFECT_IDS, errors, f"Unit {unit_id} uses unsupported status immunity {status_id}")
        role = str(unit.get("role", ""))
        ensure(role in {"melee", "ranged"}, errors, f"Unit {unit_id} uses unsupported role {role}")
        if bool(unit.get("ranged", False)):
            ensure(int(unit.get("shots", 0)) > 0, errors, f"Ranged unit {unit_id} must define shots > 0")
        if unit_id == "unit_veilmourn_undertow_harpooners":
            ensure(
                int(unit.get("min_damage", 0)) == 5 and int(unit.get("max_damage", 0)) == 8,
                errors,
                "Undertow Harpooners must retain the calibrated tier-four ranged 5-8 damage band",
            )

        abilities = unit.get("abilities", [])
        if "abilities" in unit:
            ensure(isinstance(abilities, list) and bool(abilities), errors, f"Unit {unit_id} abilities must be a non-empty list when present")
        if isinstance(abilities, list):
            seen_ability_ids: set[str] = set()
            for ability in abilities:
                ensure(isinstance(ability, dict), errors, f"Unit {unit_id} contains a non-dict ability entry")
                if not isinstance(ability, dict):
                    continue
                ability_id = str(ability.get("id", ""))
                ensure(ability_id in SUPPORTED_UNIT_ABILITY_IDS, errors, f"Unit {unit_id} uses unsupported ability {ability_id}")
                ensure(ability_id not in seen_ability_ids, errors, f"Unit {unit_id} repeats ability {ability_id}")
                ensure(bool(str(ability.get("name", ""))), errors, f"Unit {unit_id} ability {ability_id} must define name")
                ensure(bool(str(ability.get("description", ""))), errors, f"Unit {unit_id} ability {ability_id} must define description")
                if ability_id:
                    seen_ability_ids.add(ability_id)
                    authored_unit_ability_ids.add(ability_id)
                if ability_id == "reach":
                    ensure(float(ability.get("distance_one_multiplier", 0.0)) > 0.0, errors, f"Unit {unit_id} reach must define distance_one_multiplier > 0")
                    if "held_objective_types" in ability:
                        objective_types = ability.get("held_objective_types", [])
                        ensure(isinstance(objective_types, list) and bool(objective_types), errors, f"Unit {unit_id} objective reach must list held_objective_types")
                        ensure(
                            isinstance(objective_types, list) and all(str(value) in SUPPORTED_FIELD_OBJECTIVE_TYPES for value in objective_types),
                            errors,
                            f"Unit {unit_id} objective reach uses an unsupported field objective type",
                        )
                elif ability_id == "hookline":
                    ensure(not bool(unit.get("ranged", False)), errors, f"Unit {unit_id} hookline must belong to a melee unit")
                    ensure(0.0 <= float(ability.get("distance_one_multiplier", -1.0)) < 1.0, errors, f"Unit {unit_id} hookline must trade normal damage for control")
                    ensure(int(ability.get("uses_per_battle", 0)) == 1, errors, f"Unit {unit_id} hookline must be one use per battle")
                    ensure(int(ability.get("available_from_round", 0)) == 2, errors, f"Unit {unit_id} hookline must wait until round two")
                    ensure(str(ability.get("status_id", "")) == "status_rooted", errors, f"Unit {unit_id} hookline must apply status_rooted")
                    ensure(int(ability.get("duration_rounds", 0)) == 1, errors, f"Unit {unit_id} hookline must pin for one round")
                    modifiers = ability.get("modifiers", {})
                    ensure(isinstance(modifiers, dict), errors, f"Unit {unit_id} hookline modifiers must be a dictionary when present")
                elif ability_id == "rot_cant":
                    ensure(bool(unit.get("ranged", False)), errors, f"Unit {unit_id} rot_cant must belong to a ranged unit")
                    ensure(str(ability.get("status_id", "")) == "status_harried", errors, f"Unit {unit_id} rot_cant must apply status_harried")
                    ensure(int(ability.get("duration_rounds", 0)) == 1, errors, f"Unit {unit_id} rot_cant must last one round")
                    ensure(int(ability.get("uses_per_battle", 0)) == 1, errors, f"Unit {unit_id} rot_cant must be one use per battle")
                    ensure(int(ability.get("available_from_round", 0)) == 1, errors, f"Unit {unit_id} rot_cant must expose an opening support window")
                    ensure(2 <= int(ability.get("target_min_tier", 0)) <= 7, errors, f"Unit {unit_id} rot_cant must target a veteran tier")
                    ensure(0.0 < float(ability.get("ai_target_priority_bonus", 0.0)) <= 4.0, errors, f"Unit {unit_id} rot_cant ai_target_priority_bonus must be in (0, 4]")
                    modifiers = ability.get("modifiers", {})
                    ensure(isinstance(modifiers, dict) and any(isinstance(value, (int, float)) and value < 0 for value in modifiers.values()), errors, f"Unit {unit_id} rot_cant must define negative pressure")
                    ensure(0.0 < float(ability.get("wounded_threshold_ratio", 0.0)) <= 1.0, errors, f"Unit {unit_id} rot_cant wounded threshold must be in (0, 1]")
                    ensure(float(ability.get("wounded_damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} rot_cant wounded multiplier must be > 1")
                elif ability_id == "brace":
                    ensure(float(ability.get("retaliation_multiplier", 0.0)) >= 1.0, errors, f"Unit {unit_id} brace must define retaliation_multiplier >= 1")
                    ensure(int(ability.get("defending_cohesion_bonus", 0)) > 0, errors, f"Unit {unit_id} brace must define defending_cohesion_bonus > 0")
                    ensure(bool(str(ability.get("status_id", ""))), errors, f"Unit {unit_id} brace must define status_id")
                    ensure(int(ability.get("duration_rounds", 0)) > 0, errors, f"Unit {unit_id} brace must define duration_rounds > 0")
                    modifiers = ability.get("modifiers", {})
                    ensure(isinstance(modifiers, dict) and bool(modifiers), errors, f"Unit {unit_id} brace must define modifiers")
                    if "grants_base_cohesion" in ability:
                        ensure(isinstance(ability.get("grants_base_cohesion"), bool), errors, f"Unit {unit_id} brace grants_base_cohesion must be boolean")
                    if "held_objective_retaliation_multiplier" in ability or "held_objective_types" in ability:
                        ensure(float(ability.get("held_objective_retaliation_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} objective brace multiplier must be > 1")
                        objective_types = ability.get("held_objective_types", [])
                        ensure(isinstance(objective_types, list) and bool(objective_types), errors, f"Unit {unit_id} objective brace must list held_objective_types")
                        ensure(
                            isinstance(objective_types, list) and all(str(value) in SUPPORTED_FIELD_OBJECTIVE_TYPES for value in objective_types),
                            errors,
                            f"Unit {unit_id} objective brace uses an unsupported field objective type",
                        )
                    if "ally_retaliation_multiplier" in ability:
                        ensure(str(unit.get("faction_id", "")) == "faction_embercourt", errors, f"Unit {unit_id} allied retaliation aura must belong to Embercourt")
                        ensure(1.0 < float(ability.get("ally_retaliation_multiplier", 0.0)) <= 1.25, errors, f"Unit {unit_id} ally_retaliation_multiplier must be in (1, 1.25]")
                        ensure(int(ability.get("ally_retaliation_min_tier", 0)) == 4, errors, f"Unit {unit_id} allied retaliation aura must support tier-four veterans")
                        ensure(str(ability.get("ally_retaliation_role", "")) == "melee", errors, f"Unit {unit_id} allied retaliation aura must support melee lines")
                        ensure(ability.get("ally_retaliation_requires_defending") is True, errors, f"Unit {unit_id} allied retaliation aura must require defending")
                        ensure(0.0 < float(ability.get("ally_retaliation_ai_defend_bonus", 0.0)) <= 4.0, errors, f"Unit {unit_id} allied retaliation aura AI defend bonus must be in (0, 4]")
                elif ability_id == "bramble_ground":
                    ensure(not bool(unit.get("ranged", False)), errors, f"Unit {unit_id} bramble_ground must belong to a melee unit")
                    objective_types = ability.get("held_objective_types", [])
                    ensure(isinstance(objective_types, list) and bool(objective_types), errors, f"Unit {unit_id} bramble_ground must list held_objective_types")
                    ensure(
                        isinstance(objective_types, list) and all(str(value) in SUPPORTED_FIELD_OBJECTIVE_TYPES for value in objective_types),
                        errors,
                        f"Unit {unit_id} bramble_ground uses an unsupported field objective type",
                    )
                    ensure(int(ability.get("defending_cohesion_bonus", 0)) > 0, errors, f"Unit {unit_id} bramble_ground must improve held defense")
                    ensure(1.0 < float(ability.get("retaliation_multiplier", 0.0)) <= 1.25, errors, f"Unit {unit_id} bramble_ground retaliation_multiplier must be in (1, 1.25]")
                    ensure(1.0 < float(ability.get("rooted_damage_multiplier", 0.0)) <= 1.25, errors, f"Unit {unit_id} bramble_ground rooted_damage_multiplier must be in (1, 1.25]")
                    ensure(str(ability.get("status_id", "")) == "status_rooted", errors, f"Unit {unit_id} bramble_ground must apply status_rooted")
                    ensure(int(ability.get("duration_rounds", 0)) == 1, errors, f"Unit {unit_id} bramble_ground must root for one round")
                    modifiers = ability.get("modifiers", {})
                    ensure(isinstance(modifiers, dict) and bool(modifiers), errors, f"Unit {unit_id} bramble_ground must define rooted pressure modifiers")
                    ensure(0.0 < float(ability.get("ai_rooted_target_priority_bonus", 0.0)) <= 4.0, errors, f"Unit {unit_id} bramble_ground AI priority must be in (0, 4]")
                elif ability_id == "fog_screen":
                    ensure(not bool(unit.get("ranged", False)), errors, f"Unit {unit_id} fog_screen must belong to a melee unit")
                    required_tags = ability.get("required_battlefield_tags", [])
                    ensure(isinstance(required_tags, list) and bool(required_tags), errors, f"Unit {unit_id} fog_screen must list required_battlefield_tags")
                    ensure(
                        isinstance(required_tags, list) and all(str(value) in SUPPORTED_BATTLEFIELD_TAGS for value in required_tags),
                        errors,
                        f"Unit {unit_id} fog_screen uses an unsupported battlefield tag",
                    )
                    ensure(0.9 <= float(ability.get("incoming_damage_multiplier", 0.0)) < 1.0, errors, f"Unit {unit_id} fog_screen incoming_damage_multiplier must be in [0.9, 1)")
                elif ability_id == "readiness_writ":
                    ensure(str(unit.get("faction_id", "")) == "faction_embercourt", errors, f"Unit {unit_id} readiness_writ must belong to Embercourt")
                    ensure(bool(unit.get("ranged", False)), errors, f"Unit {unit_id} readiness_writ must belong to a ranged unit")
                    cleansed_status_ids = ability.get("cleansed_status_ids", [])
                    ensure(isinstance(cleansed_status_ids, list) and bool(cleansed_status_ids), errors, f"Unit {unit_id} readiness_writ must list cleansed_status_ids")
                    ensure(
                        isinstance(cleansed_status_ids, list) and all(str(value) in SUPPORTED_STATUS_EFFECT_IDS for value in cleansed_status_ids),
                        errors,
                        f"Unit {unit_id} readiness_writ uses an unsupported status id",
                    )
                    ensure(str(ability.get("preparation_status_id", "")) == "status_readiness_prepared", errors, f"Unit {unit_id} readiness_writ must define its preparation status")
                    ensure(bool(str(ability.get("preparation_status_label", ""))), errors, f"Unit {unit_id} readiness_writ must label its preparation status")
                    ensure(str(ability.get("preparation_target_role", "")) == "melee", errors, f"Unit {unit_id} readiness_writ must prepare one melee line")
                    ensure(int(ability.get("preparation_target_min_tier", 0)) == 4, errors, f"Unit {unit_id} readiness_writ must prepare a tier-four veteran line")
                    ensure(int(ability.get("preparation_duration_rounds", 0)) >= 60, errors, f"Unit {unit_id} readiness_writ preparation must persist for the bounded battle horizon")
                    ensure(int(ability.get("uses_per_battle", 0)) == 1, errors, f"Unit {unit_id} readiness_writ must be limited to one use per battle")
                    ensure(0.0 < float(ability.get("ai_attack_score_bonus", 0.0)) <= 4.0, errors, f"Unit {unit_id} readiness_writ AI attack bonus must be in (0, 4]")
                elif ability_id == "harry":
                    ensure(bool(str(ability.get("status_id", ""))), errors, f"Unit {unit_id} harry must define status_id")
                    ensure(int(ability.get("duration_rounds", 0)) > 0, errors, f"Unit {unit_id} harry must define duration_rounds > 0")
                    modifiers = ability.get("modifiers", {})
                    ensure(isinstance(modifiers, dict) and bool(modifiers), errors, f"Unit {unit_id} harry must define modifiers")
                    uses_per_battle = int(ability.get("uses_per_battle", 0))
                    ensure(uses_per_battle in (0, 1), errors, f"Unit {unit_id} harry uses_per_battle must be 0 or 1")
                    ensure(1 <= int(ability.get("target_min_tier", 1)) <= 7, errors, f"Unit {unit_id} harry target_min_tier must be between 1 and 7")
                    if uses_per_battle == 0:
                        ensure(int(ability.get("momentum_gain", 0)) > 0, errors, f"Unit {unit_id} unlimited harry must define momentum_gain > 0")
                    else:
                        ensure(int(ability.get("momentum_gain", 0)) >= 0, errors, f"Unit {unit_id} bounded harry momentum_gain must be >= 0")
                        ensure(
                            isinstance(modifiers, dict) and any(isinstance(value, (int, float)) and value < 0 for value in modifiers.values()),
                            errors,
                            f"Unit {unit_id} bounded harry must define negative pressure",
                        )
                    if "wounded_threshold_ratio" in ability:
                        ensure(0.0 < float(ability.get("wounded_threshold_ratio", 0.0)) <= 1.0, errors, f"Unit {unit_id} harry wounded_threshold_ratio must be between 0 and 1")
                    if "wounded_damage_multiplier" in ability:
                        ensure(float(ability.get("wounded_damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} harry wounded_damage_multiplier must be > 1")
                    if "shielding_damage_multiplier" in ability:
                        ensure(1.0 < float(ability.get("shielding_damage_multiplier", 0.0)) <= 1.5, errors, f"Unit {unit_id} harry shielding_damage_multiplier must be in (1, 1.5]")
                        ensure(0.0 < float(ability.get("shielding_ai_target_priority_bonus", 0.0)) <= 4.0, errors, f"Unit {unit_id} harry shielding_ai_target_priority_bonus must be in (0, 4]")
                    if "ai_target_priority_bonus" in ability:
                        ensure(0.0 <= float(ability.get("ai_target_priority_bonus", -1.0)) <= 4.0, errors, f"Unit {unit_id} harry ai_target_priority_bonus must be in [0, 4]")
                    if "target_role" in ability:
                        ensure(str(ability.get("target_role", "")) in {"melee", "ranged"}, errors, f"Unit {unit_id} harry target_role must be melee or ranged")
                    if "min_adjacent_allies_to_target" in ability:
                        ensure(not bool(unit.get("ranged", False)), errors, f"Unit {unit_id} support-gated harry must belong to a melee unit")
                        ensure(int(ability.get("min_adjacent_allies_to_target", 0)) == 1, errors, f"Unit {unit_id} support-gated harry must require exactly one adjacent ally")
                        ensure(0.0 < float(ability.get("support_ai_target_priority_bonus", 0.0)) <= 4.0, errors, f"Unit {unit_id} support-gated harry must define a bounded AI priority bonus")
                elif ability_id == "obituary":
                    modifiers = ability.get("modifiers", {})
                    ensure(bool(unit.get("ranged", False)), errors, f"Unit {unit_id} obituary must belong to a ranged unit")
                    ensure(str(ability.get("status_id", "")) == "status_obituary_marked", errors, f"Unit {unit_id} obituary must use status_obituary_marked")
                    ensure(int(ability.get("duration_rounds", 0)) == 1, errors, f"Unit {unit_id} obituary must last one round")
                    ensure(int(ability.get("uses_per_battle", 0)) == 1, errors, f"Unit {unit_id} obituary must be limited to one use per battle")
                    ensure(2 <= int(ability.get("braced_target_min_tier", 0)) <= 7, errors, f"Unit {unit_id} obituary braced_target_min_tier must be between 2 and 7")
                    ensure(0.0 < float(ability.get("braced_ai_target_priority_bonus", 0.0)) <= 10.0, errors, f"Unit {unit_id} obituary braced_ai_target_priority_bonus must be in (0, 10]")
                    ensure(isinstance(modifiers, dict), errors, f"Unit {unit_id} obituary modifiers must be an object")
                    if isinstance(modifiers, dict):
                        ensure(int(modifiers.get("cohesion", 0)) < 0, errors, f"Unit {unit_id} obituary must drain cohesion")
                        ensure(-50 <= int(modifiers.get("retaliation", 0)) < 0, errors, f"Unit {unit_id} obituary retaliation pressure must be between -50 and -1")
                    braced_modifiers = ability.get("braced_modifiers", {})
                    ensure(isinstance(braced_modifiers, dict), errors, f"Unit {unit_id} obituary braced_modifiers must be an object")
                    if isinstance(braced_modifiers, dict) and isinstance(modifiers, dict):
                        ensure(int(braced_modifiers.get("cohesion", 0)) < int(modifiers.get("cohesion", 0)), errors, f"Unit {unit_id} obituary must apply stronger cohesion pressure to veteran braced lines")
                        ensure(-50 <= int(braced_modifiers.get("retaliation", 0)) < int(modifiers.get("retaliation", 0)), errors, f"Unit {unit_id} obituary must apply stronger retaliation pressure to veteran braced lines")
                elif ability_id == "backstab":
                    ensure(float(ability.get("damage_multiplier", 0.0)) >= 1.0, errors, f"Unit {unit_id} backstab must define damage_multiplier >= 1")
                    ensure(int(ability.get("momentum_gain", 0)) > 0, errors, f"Unit {unit_id} backstab must define momentum_gain > 0")
                    if "primary_melee_only" in ability:
                        ensure(isinstance(ability.get("primary_melee_only"), bool), errors, f"Unit {unit_id} backstab primary_melee_only must be boolean")
                    status_ids = ability.get("status_ids", [])
                    ensure(isinstance(status_ids, list) and bool(status_ids), errors, f"Unit {unit_id} backstab must define status_ids")
                    if "health_threshold_ratio" in ability:
                        ensure(0.0 < float(ability.get("health_threshold_ratio", 0.0)) <= 1.0, errors, f"Unit {unit_id} backstab health_threshold_ratio must be between 0 and 1")
                    if "threshold_damage_multiplier" in ability:
                        ensure(float(ability.get("threshold_damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} backstab threshold_damage_multiplier must be > 1")
                elif ability_id == "fogwake":
                    ensure(not bool(unit.get("ranged", False)), errors, f"Unit {unit_id} fogwake must belong to a melee unit")
                    ensure(float(ability.get("isolated_damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} fogwake isolated_damage_multiplier must be > 1")
                    ensure(str(ability.get("status_id", "")) == "status_fogbound", errors, f"Unit {unit_id} fogwake must apply status_fogbound")
                    ensure(int(ability.get("duration_rounds", 0)) == 1, errors, f"Unit {unit_id} fogwake must last one round")
                    ensure(0.0 < float(ability.get("ai_target_priority_bonus", 0.0)) <= 4.0, errors, f"Unit {unit_id} fogwake ai_target_priority_bonus must be in (0, 4]")
                    modifiers = ability.get("modifiers", {})
                    ensure(isinstance(modifiers, dict), errors, f"Unit {unit_id} fogwake modifiers must be an object")
                    if isinstance(modifiers, dict):
                        ensure(int(modifiers.get("defense", 0)) < 0, errors, f"Unit {unit_id} fogwake must reduce defense")
                        ensure(int(modifiers.get("initiative", 0)) < 0, errors, f"Unit {unit_id} fogwake must reduce initiative")
                        ensure(int(modifiers.get("cohesion", 0)) < 0, errors, f"Unit {unit_id} fogwake must reduce cohesion")
                elif ability_id == "shielding":
                    multiplier = float(ability.get("ranged_damage_multiplier", 0.0))
                    ensure(0.0 < multiplier <= 1.0, errors, f"Unit {unit_id} shielding must define ranged_damage_multiplier between 0 and 1")
                    if "snare_vulnerable" in ability:
                        ensure(ability.get("snare_vulnerable") is True, errors, f"Unit {unit_id} shielding snare_vulnerable must be true when present")
                    ensure("cohesion_hold_bonus" in ability, errors, f"Unit {unit_id} shielding must define cohesion_hold_bonus")
                    ensure(int(ability.get("cohesion_hold_bonus", 0)) >= 0, errors, f"Unit {unit_id} shielding cohesion_hold_bonus must be >= 0")
                    if "engaged_damage_multiplier" in ability:
                        ensure(float(ability.get("engaged_damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} shielding engaged_damage_multiplier must be > 1")
                    if "harried_damage_multiplier" in ability:
                        ensure(float(ability.get("harried_damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} shielding harried_damage_multiplier must be > 1")
                    if "payoff_status_ids" in ability:
                        ensure(isinstance(ability.get("payoff_status_ids", []), list) and bool(ability.get("payoff_status_ids", [])), errors, f"Unit {unit_id} shielding payoff_status_ids must be a non-empty list")
                    if "ally_ranged_melee_damage_reduction_pct" in ability:
                        reduction_pct = int(ability.get("ally_ranged_melee_damage_reduction_pct", 0))
                        ensure(0 <= reduction_pct <= 50, errors, f"Unit {unit_id} shielding ally_ranged_melee_damage_reduction_pct must be between 0 and 50")
                    if "linebreaker_screen_bonus_pct" in ability:
                        linebreaker_bonus_pct = int(ability.get("linebreaker_screen_bonus_pct", 0))
                        ensure(0 < linebreaker_bonus_pct <= 50, errors, f"Unit {unit_id} shielding linebreaker_screen_bonus_pct must be between 1 and 50")
                    if "ranged_damage_return_ratio" in ability:
                        return_ratio = float(ability.get("ranged_damage_return_ratio", 0.0))
                        ensure(0.0 < return_ratio <= 0.25, errors, f"Unit {unit_id} shielding ranged_damage_return_ratio must be in (0, 0.25]")
                    if "linked_ranged_unit_ids" in ability or "linked_ranged_damage_reduction_pct" in ability:
                        linked_unit_ids = ability.get("linked_ranged_unit_ids", [])
                        ensure(isinstance(linked_unit_ids, list) and bool(linked_unit_ids), errors, f"Unit {unit_id} shielding linked_ranged_unit_ids must be a non-empty list")
                        for linked_unit_id in linked_unit_ids if isinstance(linked_unit_ids, list) else []:
                            ensure(str(linked_unit_id) in units, errors, f"Unit {unit_id} shielding references unknown linked ranged unit {linked_unit_id}")
                            ensure(bool(units.get(str(linked_unit_id), {}).get("ranged", False)), errors, f"Unit {unit_id} shielding linked unit {linked_unit_id} must be ranged")
                        linked_reduction_pct = int(ability.get("linked_ranged_damage_reduction_pct", 0))
                        ensure(0 < linked_reduction_pct <= 50, errors, f"Unit {unit_id} shielding linked_ranged_damage_reduction_pct must be between 1 and 50")
                elif ability_id == "volley":
                    ensure(float(ability.get("damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} volley must define damage_multiplier > 1")
                    ensure(int(ability.get("min_distance", 0)) > 0, errors, f"Unit {unit_id} volley must define min_distance > 0")
                    if "status_ids" in ability:
                        ensure(isinstance(ability.get("status_ids", []), list) and bool(ability.get("status_ids", [])), errors, f"Unit {unit_id} volley status_ids must be a non-empty list when present")
                    if "status_damage_multiplier" in ability:
                        ensure(float(ability.get("status_damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} volley status_damage_multiplier must be > 1")
                    if "ally_defending_multiplier" in ability:
                        ensure(float(ability.get("ally_defending_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} volley ally_defending_multiplier must be > 1")
                    if bool(ability.get("requires_protected_lane", False)):
                        objective_types = ability.get("protected_lane_objective_types", [])
                        ensure(isinstance(objective_types, list) and bool(objective_types), errors, f"Unit {unit_id} protected volley must list protected_lane_objective_types")
                        ensure(
                            isinstance(objective_types, list) and all(str(value) in SUPPORTED_FIELD_OBJECTIVE_TYPES for value in objective_types),
                            errors,
                            f"Unit {unit_id} protected volley uses an unsupported field objective type",
                        )
                elif ability_id == "formation_guard":
                    ensure(float(ability.get("ally_ranged_damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} formation_guard must define ally_ranged_damage_multiplier > 1")
                    ensure(int(ability.get("ally_ranged_initiative_bonus", 0)) > 0, errors, f"Unit {unit_id} formation_guard must define ally_ranged_initiative_bonus > 0")
                    ensure(int(ability.get("ally_cohesion_bonus", 0)) > 0, errors, f"Unit {unit_id} formation_guard must define ally_cohesion_bonus > 0")
                    ensure(int(ability.get("defending_cohesion_bonus", 0)) > 0, errors, f"Unit {unit_id} formation_guard must define defending_cohesion_bonus > 0")
                    ensure(int(ability.get("defending_initiative_bonus", 0)) > 0, errors, f"Unit {unit_id} formation_guard must define defending_initiative_bonus > 0")
                    ensure(float(ability.get("staggered_damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} formation_guard must define staggered_damage_multiplier > 1")
                elif ability_id == "resonance_relay":
                    ensure(str(unit.get("faction_id", "")) == "faction_sunvault", errors, f"Unit {unit_id} resonance_relay must belong to Sunvault")
                    ensure(int(unit.get("tier", 0)) >= 4, errors, f"Unit {unit_id} resonance_relay must enter at tier four or later")
                    minimum = int(ability.get("minimum_calibrated_stacks", 0))
                    maximum = int(ability.get("maximum_calibrated_stacks", 0))
                    ensure(2 <= minimum <= maximum <= 6, errors, f"Unit {unit_id} resonance_relay calibrated stack bounds must satisfy 2 <= minimum <= maximum <= 6")
                    ensure(0.0 < float(ability.get("line_damage_per_calibrated_stack", 0.0)) <= 0.1, errors, f"Unit {unit_id} resonance_relay line damage must be in (0, 0.1]")
                    ensure(0 < int(ability.get("line_initiative_bonus", 0)) <= 3, errors, f"Unit {unit_id} resonance_relay line initiative bonus must be in [1, 3]")
                    ensure(0 < int(ability.get("late_round_initiative_bonus", 0)) <= 3, errors, f"Unit {unit_id} resonance_relay late-round initiative bonus must be in [1, 3]")
                    ensure(0 < int(ability.get("terrain_momentum_bonus", 0)) <= 3, errors, f"Unit {unit_id} resonance_relay terrain momentum bonus must be in [1, 3]")
                    linked_unit_ids = ability.get("linked_unit_ids", [])
                    ensure(linked_unit_ids == ["unit_sunvault_prism_adepts"], errors, f"Unit {unit_id} resonance_relay must link the Prism Adept stack")
                    ensure(0 < int(ability.get("linked_initiative_bonus", 0)) <= 3, errors, f"Unit {unit_id} resonance_relay linked initiative bonus must be in [1, 3]")
                elif ability_id == "bloodrush":
                    if "primary_melee_only" in ability:
                        ensure(isinstance(ability.get("primary_melee_only"), bool), errors, f"Unit {unit_id} bloodrush primary_melee_only must be boolean")
                    if bool(ability.get("primary_melee_only", False)):
                        ensure(not bool(unit.get("ranged", False)), errors, f"Unit {unit_id} primary-melee bloodrush must belong to a melee unit")
                    if "clean_target_damage_multiplier" in ability:
                        ensure(0.25 <= float(ability.get("clean_target_damage_multiplier", 0.0)) <= 1.0, errors, f"Unit {unit_id} bloodrush clean_target_damage_multiplier must be between 0.25 and 1")
                    ensure(0.0 < float(ability.get("wounded_threshold_ratio", 0.0)) <= 1.0, errors, f"Unit {unit_id} bloodrush wounded_threshold_ratio must be between 0 and 1")
                    ensure(float(ability.get("wounded_damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} bloodrush wounded_damage_multiplier must be > 1")
                    ensure(isinstance(ability.get("status_ids", []), list) and bool(ability.get("status_ids", [])), errors, f"Unit {unit_id} bloodrush must define status_ids")
                    ensure(float(ability.get("status_damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} bloodrush status_damage_multiplier must be > 1")
                    if "isolated_damage_multiplier" in ability:
                        ensure(ability.get("primary_melee_only") is True, errors, f"Unit {unit_id} isolated bloodrush must be primary-melee only")
                        ensure(1.0 < float(ability.get("isolated_damage_multiplier", 0.0)) <= 1.25, errors, f"Unit {unit_id} bloodrush isolated_damage_multiplier must be in (1, 1.25]")
                        ensure(0.0 < float(ability.get("isolated_ai_target_priority_bonus", 0.0)) <= 5.0, errors, f"Unit {unit_id} isolated bloodrush must define bounded AI target priority")
                    ensure(int(ability.get("wounded_initiative_bonus", 0)) > 0, errors, f"Unit {unit_id} bloodrush wounded_initiative_bonus must be > 0")
                    ensure(int(ability.get("max_initiative_bonus", 0)) > 0, errors, f"Unit {unit_id} bloodrush max_initiative_bonus must be > 0")
                    ensure(int(ability.get("momentum_gain", 0)) >= 0, errors, f"Unit {unit_id} bloodrush momentum_gain must be >= 0")
                    ensure(int(ability.get("kill_momentum_gain", 0)) > 0, errors, f"Unit {unit_id} bloodrush kill_momentum_gain must be > 0")
                    ensure(int(ability.get("momentum_gain", 0)) + int(ability.get("kill_momentum_gain", 0)) > 0, errors, f"Unit {unit_id} bloodrush must gain momentum from wounded contact or a kill")
                    ensure(0 <= int(ability.get("late_round_initiative_bonus", 0)) <= 3, errors, f"Unit {unit_id} bloodrush late_round_initiative_bonus must be between 0 and 3")
                elif ability_id == "solar_array_lane":
                    ensure(str(unit.get("faction_id", "")) == "faction_sunvault", errors, f"Unit {unit_id} solar_array_lane must belong to Sunvault")
                    ensure(not bool(unit.get("ranged", False)), errors, f"Unit {unit_id} solar_array_lane must belong to a melee screen")
                    ensure(float(ability.get("incoming_melee_damage_multiplier", 0.0)) == 0.95, errors, f"Unit {unit_id} solar_array_lane incoming multiplier must equal 0.95")
                    ensure(ability.get("linked_unit_ids", []) == ["unit_sunvault_daybreak_colossus"], errors, f"Unit {unit_id} solar_array_lane must link the Daybreak Colossus")
                elif ability_id == "overheat":
                    ensure(not bool(unit.get("ranged", False)), errors, f"Unit {unit_id} overheat must belong to a melee unit")
                    ensure(float(ability.get("burst_damage_multiplier", 0.0)) > 1.0, errors, f"Unit {unit_id} overheat burst_damage_multiplier must be > 1")
                    overheated_multiplier = float(ability.get("overheated_damage_multiplier", 0.0))
                    ensure(0.0 < overheated_multiplier < 1.0, errors, f"Unit {unit_id} overheat overheated_damage_multiplier must be between 0 and 1")
                    ensure(str(ability.get("status_id", "")) == "status_overheated", errors, f"Unit {unit_id} overheat must use status_overheated")
                    ensure(int(ability.get("duration_rounds", 0)) == 2, errors, f"Unit {unit_id} overheat duration_rounds must equal 2")
                    modifiers = ability.get("modifiers", {})
                    ensure(isinstance(modifiers, dict), errors, f"Unit {unit_id} overheat modifiers must be a dictionary")
                    if isinstance(modifiers, dict):
                        ensure(int(modifiers.get("defense", 0)) < 0, errors, f"Unit {unit_id} overheat must reduce defense")
                        ensure(int(modifiers.get("initiative", 0)) < 0, errors, f"Unit {unit_id} overheat must reduce initiative")
                elif ability_id == "pressure_artillery":
                    ensure(bool(unit.get("ranged", False)), errors, f"Unit {unit_id} pressure_artillery must belong to a ranged unit")
                    ensure(int(ability.get("cluster_range", 0)) == 1, errors, f"Unit {unit_id} pressure_artillery cluster_range must equal one")
                    ensure(1 <= int(ability.get("secondary_damage_per_unit", 0)) <= 4, errors, f"Unit {unit_id} pressure_artillery secondary_damage_per_unit must be in [1, 4]")
                    ensure(1 <= int(ability.get("max_secondary_damage", 0)) <= 30, errors, f"Unit {unit_id} pressure_artillery max_secondary_damage must be in [1, 30]")
                    ensure(int(ability.get("max_secondary_targets", 0)) == 1, errors, f"Unit {unit_id} pressure_artillery must hit exactly one secondary target")
                    ensure(str(ability.get("status_id", "")) == "status_overheated", errors, f"Unit {unit_id} pressure_artillery must use the shared status_overheated heat state")
                    ensure(int(ability.get("duration_rounds", 0)) == 2, errors, f"Unit {unit_id} pressure_artillery heat must last two rounds")
                    modifiers = ability.get("modifiers", {})
                    ensure(isinstance(modifiers, dict), errors, f"Unit {unit_id} pressure_artillery modifiers must be a dictionary")
                    if isinstance(modifiers, dict):
                        ensure(int(modifiers.get("initiative", 0)) < 0, errors, f"Unit {unit_id} pressure_artillery heat must reduce initiative")
                        ensure("defense" not in modifiers, errors, f"Unit {unit_id} pressure_artillery heat must not reuse the Debt Furnace defense penalty")
                    ensure(0.0 < float(ability.get("ai_heat_score_penalty", 0.0)) <= 4.0, errors, f"Unit {unit_id} pressure_artillery must define a bounded tactical-AI heat cost")
                elif ability_id == "counter_ambush_flare":
                    ensure(str(unit.get("faction_id", "")) == "faction_embercourt", errors, f"Unit {unit_id} counter_ambush_flare must belong to Embercourt")
                    ensure(not bool(unit.get("ranged", False)), errors, f"Unit {unit_id} counter_ambush_flare must belong to a melee unit")
                    ensure(ability.get("countered_ability_ids", []) == ["backstab", "fogwake"], errors, f"Unit {unit_id} counter_ambush_flare must counter exactly backstab and fogwake")
                    ensure(float(ability.get("ambush_bonus_retention", -1.0)) == 0.0, errors, f"Unit {unit_id} counter_ambush_flare must remove only the authored ambush bonus")
                    ensure(ability.get("blocks_ambush_status") is True, errors, f"Unit {unit_id} counter_ambush_flare must block Fogbound application")
                    ensure(str(ability.get("revealed_status_id", "")) == "status_flare_revealed", errors, f"Unit {unit_id} counter_ambush_flare must apply status_flare_revealed")
                    ensure(int(ability.get("revealed_duration_rounds", 0)) == 1, errors, f"Unit {unit_id} counter_ambush_flare reveal must last one round")
                    ensure(ability.get("revealed_ability_ids", []) == ["fogwake"], errors, f"Unit {unit_id} counter_ambush_flare must reveal only a denied fogwake ambusher")
                    ensure(ability.get("revealed_modifiers", {}) == {"defense": -1, "initiative": -1}, errors, f"Unit {unit_id} counter_ambush_flare reveal must reduce defense and initiative by one")
                elif ability_id == "sporeglass_mend":
                    ensure(str(unit.get("faction_id", "")) == "faction_thornwake", errors, f"Unit {unit_id} sporeglass_mend must belong to Thornwake")
                    ensure(bool(unit.get("ranged", False)), errors, f"Unit {unit_id} sporeglass_mend must belong to a ranged unit")
                    ensure(int(ability.get("health_per_mender", 0)) == 3, errors, f"Unit {unit_id} sporeglass_mend health_per_mender must equal 3")
                    ensure(int(ability.get("max_health_per_attack", 0)) == 8, errors, f"Unit {unit_id} sporeglass_mend max_health_per_attack must equal 8")
                elif ability_id == "foundry_aura":
                    ensure(str(unit.get("faction_id", "")) == "faction_brasshollow", errors, f"Unit {unit_id} foundry_aura must belong to Brasshollow")
                    ensure(int(ability.get("ally_defense_bonus", 0)) > 0, errors, f"Unit {unit_id} foundry_aura ally_defense_bonus must be > 0")
                    ensure(ability.get("hardening_requires_overheated") is True, errors, f"Unit {unit_id} foundry_aura must harden only Overheated allies")
                    ensure(0.0 < float(ability.get("round_repair_pct", 0.0)) <= 0.1, errors, f"Unit {unit_id} foundry_aura round_repair_pct must be in (0, 0.1]")
                    ensure(0.0 < float(ability.get("overheated_repair_bonus_pct", 0.0)) <= 0.1, errors, f"Unit {unit_id} foundry_aura overheated_repair_bonus_pct must be in (0, 0.1]")
                    ensure(float(ability.get("ai_target_priority_bonus", 0.0)) > 0.0, errors, f"Unit {unit_id} foundry_aura ai_target_priority_bonus must be > 0")

    ensure(
        {"reach", "hookline", "rot_cant", "brace", "bramble_ground", "fog_screen", "readiness_writ", "harry", "backstab", "shielding", "volley", "formation_guard", "resonance_relay", "solar_array_lane", "bloodrush", "obituary", "overheat", "pressure_artillery", "counter_ambush_flare", "sporeglass_mend", "foundry_aura"}.issubset(authored_unit_ability_ids),
        errors,
        "Authored units must cover the combat-depth ability set: reach, hookline, rot_cant, brace, bramble_ground, fog_screen, readiness_writ, harry, backstab, shielding, volley, formation_guard, resonance_relay, solar_array_lane, bloodrush, obituary, overheat, pressure_artillery, counter_ambush_flare, sporeglass_mend, and foundry_aura",
    )

    obituary_scribes = units.get("unit_veilmourn_obituary_scribes", {})
    obituary_ability = next(
        (ability for ability in obituary_scribes.get("abilities", []) if isinstance(ability, dict) and str(ability.get("id", "")) == "obituary"),
        {},
    )
    ensure(bool(obituary_ability), errors, "Veilmourn Obituary Scribes must retain Final Notice obituary pressure")

    thornwhip_carriers = units.get("unit_thornwake_thornwhip_carriers", {})
    thornwhip_root_brace = next(
        (
            ability
            for ability in thornwhip_carriers.get("abilities", [])
            if isinstance(ability, dict) and str(ability.get("name", "")) == "Root Brace"
        ),
        {},
    )
    ensure(str(thornwhip_root_brace.get("id", "")) == "brace", errors, "Thornwake Thornwhip Carriers must own Root Brace")
    ensure(str(thornwhip_root_brace.get("status_id", "")) == "status_rooted", errors, "Thornwake Root Brace must apply status_rooted")
    ember_lantern_sappers = units.get("unit_embercourt_lantern_sappers", {})
    ensure(
        not any(isinstance(ability, dict) and str(ability.get("id", "")) == "brace" for ability in ember_lantern_sappers.get("abilities", [])),
        errors,
        "Embercourt Lantern Sappers must not own Thornwake's brace ability",
    )
    lantern_flare = next(
        (ability for ability in ember_lantern_sappers.get("abilities", []) if isinstance(ability, dict) and str(ability.get("id", "")) == "counter_ambush_flare"),
        {},
    )
    ensure(str(lantern_flare.get("name", "")) == "Counter-Ambush Flare", errors, "Lantern Sappers must own Counter-Ambush Flare")
    counter_ambush_flare_owners = sorted(
        unit_id
        for unit_id, unit in units.items()
        if any(isinstance(ability, dict) and str(ability.get("id", "")) == "counter_ambush_flare" for ability in unit.get("abilities", []))
    )
    ensure(counter_ambush_flare_owners == ["unit_embercourt_lantern_sappers"], errors, "Counter-Ambush Flare must remain exclusive to Embercourt Lantern Sappers")

    reedsnare_kin = units.get("unit_mireclaw_reedsnare_kin", {})
    reedsnare_harry = next((ability for ability in reedsnare_kin.get("abilities", []) if isinstance(ability, dict) and str(ability.get("id", "")) == "harry"), {})
    ensure(str(reedsnare_harry.get("name", "")) == "Reed-Circle Snare", errors, "Reedsnare Kin must own Reed-Circle Snare")
    ensure(str(reedsnare_harry.get("status_id", "")) == "status_mire_harried", errors, "Reed-Circle Snare must create the isolated Mireclaw setup state")
    ensure(int(reedsnare_harry.get("min_adjacent_allies_to_target", 0)) == 1, errors, "Reed-Circle Snare must require one allied surrounding stack")
    ensure(int(reedsnare_harry.get("target_min_tier", 0)) == 4, errors, "Reed-Circle Snare must be reserved for veteran targets")
    ensure(str(reedsnare_harry.get("target_role", "")) == "melee", errors, "Reed-Circle Snare must target melee veterans")
    ensure(float(reedsnare_harry.get("ai_target_priority_bonus", -1.0)) == 0.1, errors, "Reed-Circle Snare must keep a narrow base target priority")
    ensure(reedsnare_harry.get("modifiers", {}) == {"cohesion": -1}, errors, "Reed-Circle Snare must reduce only cohesion by one")

    mudglass_slingers = units.get("unit_mireclaw_mudglass_slingers", {})
    mudglass_harry = next((ability for ability in mudglass_slingers.get("abilities", []) if isinstance(ability, dict) and str(ability.get("id", "")) == "harry"), {})
    ensure(str(mudglass_harry.get("name", "")) == "Mudglass Blind", errors, "Mudglass Slingers must own Mudglass Blind")
    ensure(str(mudglass_harry.get("status_id", "")) == "status_mire_harried", errors, "Mudglass Blind must create the isolated Mireclaw setup state")
    ensure(int(mudglass_harry.get("target_min_tier", 0)) == 4, errors, "Mudglass Blind must be reserved for veteran targets")
    ensure(str(mudglass_harry.get("target_role", "")) == "melee", errors, "Mudglass Blind must target melee veterans")
    ensure(float(mudglass_harry.get("ai_target_priority_bonus", -1.0)) == 0.05, errors, "Mudglass Blind must keep a narrow target priority")
    ensure(mudglass_harry.get("modifiers", {}) == {"attack": -1}, errors, "Mudglass Blind must reduce only attack by one")

    bogplate_maulers = units.get("unit_mireclaw_bogplate_maulers", {})
    bogplate_shielding = next((ability for ability in bogplate_maulers.get("abilities", []) if isinstance(ability, dict) and str(ability.get("id", "")) == "shielding"), {})
    ensure(str(bogplate_shielding.get("name", "")) == "Bogplate Hide", errors, "Bogplate Maulers must own Bogplate Hide")
