        'parent_probe.z_index = 100',
        "_destructive_parent_click_geometry(parent_probe, dialog)",
        '"workflow_owner_exact"',
        '"fingerprint_exact"',
        '"parent_probe_blocked"',
        '"settings_dock_open_exact"',
        '"settings_tab_exact"',
        '"runtime_restored_exact"',
