def validate_town_shell_release_polish(errors: list[str]) -> None:
    town_visual_smoke_path = ROOT / "tests" / "town_battle_visual_smoke.gd"
    town_exit_profile_path = ROOT / "tests" / "town_exit_profile_accuracy_regression.gd"
